//! UniFFI's bindings generator, vendored as a binary so the Kotlin and Swift sources
//! are generated by the *same* `uniffi` version the scaffolding was compiled against
//! (SPEC §11.7.1). A mismatch between the two is a silent ABI break, which is exactly
//! the class of failure §11.8 exists to prevent.
//!
//! Generate from the built `cdylib` (library mode), never from a hand-written UDL —
//! the metadata then comes out of the artifact that will actually be linked:
//!
//! ```sh
//! cargo build -p misty-ffi
//! cargo run -p misty-ffi --features cli --bin uniffi-bindgen -- \
//!     generate --library target/debug/libmisty_ffi.so \
//!     --language swift --out-dir target/bindings/swift
//! ```

fn main() {
    uniffi::uniffi_bindgen_main();
}
